"use client";

import { useEffect, useId, useMemo, useRef, useState, type ComponentProps, type ReactNode } from "react";

import { IconChevronLeft, IconChevronRight, IconChevronsLeft, IconChevronsRight } from "@rhs-ui/icons";
import { Pane } from "@rhs-ui/application/transfer-list/pane";
import {
  DEFAULT_LABELS,
  EMPTY_PANE,
  fill,
  filterItems,
  knownIds,
  nextActive,
  selectedIn,
  type PaneState,
  type Side,
  type TransferItem,
  type TransferListLabels,
  type TransferTitles,
} from "@rhs-ui/application/transfer-list/transfer";
import { Button } from "@rhs-ui/primitives/button";
import { cn } from "@/lib/utils";

export type { TransferItem, TransferListLabels, TransferTitles } from "@rhs-ui/application/transfer-list/transfer";

export interface TransferListProps extends Omit<ComponentProps<"div">, "defaultValue" | "onChange" | "children"> {
  /** Everything that can be chosen, with an id, a label and an optional second line. A disabled item cannot be moved. */
  items: readonly TransferItem[];
  /** The ids of the chosen items, in the order to show them, when you control the lists. New items are added at the end. */
  value?: readonly string[];
  /** The ids to begin with, when the component keeps them itself. */
  defaultValue?: readonly string[];
  /** Called with all the chosen ids whenever items are added or removed. */
  onValueChange?: (value: string[]) => void;
  /** The headings of the two lists. Default "Available" and "Chosen". */
  titles?: TransferTitles;
  /** Give each list a search field. Default true. */
  searchable?: boolean;
  /** The height of each list: a number of px or any CSS length. Default 18rem, 14rem when the lists are stacked. */
  height?: number | string;
  /** A name for a plain form submit: one hidden input per chosen id. */
  name?: string;
  /** Turn the whole thing off. */
  disabled?: boolean;
  /** The language of the plural rules for the announcements. Default "en-US". */
  locale?: string;
  /** The words the lists say, for translation. */
  labels?: TransferListLabels;
}

interface MoveButtonProps {
  /** What the button does, in full: it names the button for assistive technology and is its tooltip ("Add all (3 shown)"). */
  label: string;
  /** The word under the chevron while the buttons lie in a row between stacked lists ("Add all"), without the count of a search. Beside the lists the chevron is enough. */
  text: string;
  disabled: boolean;
  onClick: () => void;
  children: ReactNode;
}

/** One of the four buttons between the lists: a chevron, with its word under it when the lists are stacked, where a row of bare chevrons says nothing on a phone. */
function MoveButton({ label, text, disabled, onClick, children }: MoveButtonProps): React.JSX.Element {
  return (
    <Button type="button" variant="outline" disabled={disabled} title={label} aria-label={label} onClick={onClick} className="h-auto w-full min-w-0 flex-col gap-0.5 px-1 py-1.5 @2xl:size-9 @2xl:flex-row @2xl:p-0">
      {children}
      <span aria-hidden="true" className="text-center text-[0.6875rem] leading-3.5 font-medium text-balance @2xl:sr-only">
        {text}
      </span>
    </Button>
  );
}

/**
 * A dual list for giving many things to something: members to a project,
 * columns to a view, permissions to a role. Each list is a multi-select
 * listbox with a search field and an "N of M selected" header; Add, Add all,
 * Remove and Remove all are real buttons named for what they do and disabled
 * when they would do nothing, and double-click or Enter on an item moves it.
 * After a move the cursor stays where the items were, so the keyboard carries
 * on from the same place, and the move is announced ("3 items added to
 * Chosen"). When the container is narrow the lists stack and the buttons lie
 * in a row between them, each with its word under the chevron.
 */
export function TransferList({ items, value, defaultValue, onValueChange, titles, searchable = true, height, name, disabled = false, locale = "en-US", labels, className, ...props }: TransferListProps) {
  const words = { ...DEFAULT_LABELS, ...labels };
  const names: Record<Side, string> = { available: titles?.available ?? "Available", chosen: titles?.chosen ?? "Chosen" };
  const base = useId();
  const [own, setOwn] = useState<readonly string[]>(defaultValue ?? []);
  const [panes, setPanes] = useState<Record<Side, PaneState>>({ available: EMPTY_PANE, chosen: EMPTY_PANE });
  const [fresh, setFresh] = useState<ReadonlySet<string>>(new Set());
  const [said, setSaid] = useState("");
  // Where the focus should go after a move, when the move took away what had it.
  const [land, setLand] = useState<{ side: Side } | null>(null);
  const availableList = useRef<HTMLDivElement | null>(null);
  const chosenList = useRef<HTMLDivElement | null>(null);
  const timer = useRef<number | undefined>(undefined);

  const chosenIds = knownIds(value ?? own, items);
  const chosenSet = new Set(chosenIds);
  const index = useMemo(() => new Map(items.map((item, at) => [item.id, at] as const)), [items]);
  const byId = useMemo(() => new Map(items.map((item) => [item.id, item] as const)), [items]);
  const lists: Record<Side, TransferItem[]> = {
    available: items.filter((item) => !chosenSet.has(item.id)),
    chosen: chosenIds.flatMap((id) => byId.get(id) ?? []),
  };
  const shown: Record<Side, TransferItem[]> = { available: filterItems(lists.available, panes.available.query), chosen: filterItems(lists.chosen, panes.chosen.query) };
  const picked: Record<Side, TransferItem[]> = { available: selectedIn(shown.available, panes.available.selected), chosen: selectedIn(shown.chosen, panes.chosen.selected) };
  const everything: Record<Side, TransferItem[]> = { available: shown.available.filter((item) => !item.disabled), chosen: shown.chosen.filter((item) => !item.disabled) };

  useEffect(() => {
    if (land) (land.side === "available" ? availableList : chosenList).current?.focus({ preventScroll: true });
  }, [land]);

  useEffect(() => () => window.clearTimeout(timer.current), []);

  const noun = (count: number) => (new Intl.PluralRules(locale).select(count) === "one" ? words.itemOne : words.itemOther);

  function patch(side: Side, change: Partial<PaneState>) {
    setPanes((before) => ({ ...before, [side]: { ...before[side], ...change } }));
  }

  /** Moves items out of one list into the other, and tells people. `by` says what asked: a button, or the list itself (Enter, a double click). */
  function move(from: Side, ids: readonly string[], by: "button" | "list") {
    if (disabled || ids.length === 0) return;
    const to: Side = from === "available" ? "chosen" : "available";
    const leaving = new Set(ids);
    const next = from === "available" ? [...chosenIds, ...items.filter((item) => leaving.has(item.id)).map((item) => item.id)] : chosenIds.filter((id) => !leaving.has(id));
    if (value === undefined) setOwn(next);
    onValueChange?.(next);

    // The cursor stays where the items were, and what was selected goes with them.
    setPanes((before) => {
      const pane = before[from];
      return { ...before, [from]: { ...pane, selected: new Set([...pane.selected].filter((id) => !leaving.has(id))), anchor: null, seed: new Set<string>(), active: nextActive(shown[from], leaving) } };
    });
    setFresh(new Set(ids));
    window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => setFresh(new Set()), 1600);
    setSaid(fill(from === "available" ? words.added : words.removed, { count: ids.length, noun: noun(ids.length), list: names.chosen }));

    // A button that moved something may have switched itself off, and a list that is now empty cannot hold the focus: put it where it can carry on.
    const left = shown[from].filter((item) => !leaving.has(item.id));
    if (left.length === 0) setLand({ side: to });
    else if (by === "button") setLand({ side: from });
  }

  const idsOf = (list: readonly TransferItem[]) => list.map((item) => item.id);
  const domId = (side: Side) => (id: string) => `${base}-${side}-${index.get(id) ?? id}`;
  const filtered = (side: Side) => panes[side].query.trim() !== "";

  /** A button's name: "Add all", or "Add all (3 shown)" while a search narrows it. */
  const nameOf = (label: string, side: Side) => (filtered(side) ? fill(words.shown, { label, count: everything[side].length }) : label);

  const moveButtons = (
    <div role="group" aria-label={words.moveGroup} data-slot="transfer-list-actions" className="grid grid-cols-4 gap-2 @2xl:grid-cols-1 @2xl:self-center">
      <MoveButton label={words.add} text={words.add} disabled={disabled || picked.available.length === 0} onClick={() => move("available", idsOf(picked.available), "button")}>
        <IconChevronRight aria-hidden="true" className="rotate-90 @2xl:rotate-0" />
      </MoveButton>
      <MoveButton label={nameOf(words.addAll, "available")} text={words.addAll} disabled={disabled || everything.available.length === 0} onClick={() => move("available", idsOf(everything.available), "button")}>
        <IconChevronsRight aria-hidden="true" className="rotate-90 @2xl:rotate-0" />
      </MoveButton>
      <MoveButton label={words.remove} text={words.remove} disabled={disabled || picked.chosen.length === 0} onClick={() => move("chosen", idsOf(picked.chosen), "button")}>
        <IconChevronLeft aria-hidden="true" className="rotate-90 @2xl:rotate-0" />
      </MoveButton>
      <MoveButton label={nameOf(words.removeAll, "chosen")} text={words.removeAll} disabled={disabled || everything.chosen.length === 0} onClick={() => move("chosen", idsOf(everything.chosen), "button")}>
        <IconChevronsLeft aria-hidden="true" className="rotate-90 @2xl:rotate-0" />
      </MoveButton>
    </div>
  );

  return (
    <div data-slot="transfer-list" className={cn("@container w-full min-w-0", disabled && "opacity-60", className)} {...props}>
      <div className="grid gap-3 @2xl:grid-cols-[minmax(0,1fr)_auto_minmax(0,1fr)] @2xl:gap-4">
        <Pane
          side="available"
          title={names.available}
          items={lists.available}
          domId={domId("available")}
          state={panes.available}
          onChange={(change) => patch("available", change)}
          onMove={(ids) => move("available", ids, "list")}
          fresh={fresh}
          searchable={searchable}
          height={height}
          disabled={disabled}
          empty={words.emptyAvailable}
          words={words}
          listRef={availableList}
        />
        {moveButtons}
        <Pane
          side="chosen"
          title={names.chosen}
          items={lists.chosen}
          domId={domId("chosen")}
          state={panes.chosen}
          onChange={(change) => patch("chosen", change)}
          onMove={(ids) => move("chosen", ids, "list")}
          fresh={fresh}
          searchable={searchable}
          height={height}
          disabled={disabled}
          empty={fill(words.emptyChosen, { list: names.available })}
          words={words}
          listRef={chosenList}
        />
      </div>

      {name ? chosenIds.map((id) => <input key={id} type="hidden" name={name} value={id} />) : null}

      {/* Kept in the page when empty: a live region that appears together with its message is often never read. */}
      <p role="status" aria-live="polite" className="sr-only">
        {said}
      </p>
    </div>
  );
}

"use client";

import { useEffect, useId, useMemo, useState, type KeyboardEvent, type MouseEvent, type RefObject } from "react";

import { IconCheck, IconLock } from "@rhs-ui/icons";
import { filterItems, fill, rangeBetween, selectedIn, toggled, type PaneState, type Side, type TransferItem, type Words } from "@rhs-ui/application/transfer-list/transfer";
import { Checkbox } from "@rhs-ui/primitives/checkbox";
import { SearchInput } from "@rhs-ui/primitives/search-input";
import { cn } from "@/lib/utils";

export interface PaneProps {
  side: Side;
  /** The list's heading, which also names it for a screen reader. */
  title: string;
  /** Every item in this list, in the order to show them. */
  items: readonly TransferItem[];
  /** The id of an item's element in the page, for aria-activedescendant. */
  domId: (id: string) => string;
  state: PaneState;
  onChange: (change: Partial<PaneState>) => void;
  /** Called with the ids to move to the other list: Enter on an item, or a double click. */
  onMove: (ids: readonly string[]) => void;
  /** The items that were moved here a moment ago: they are tinted, and scrolled into view. */
  fresh: ReadonlySet<string>;
  searchable: boolean;
  height?: number | string;
  disabled: boolean;
  /** What the list says when it has no items at all. */
  empty: string;
  words: Words;
  /** The list itself, so the parent can put the focus back on it after a move. */
  listRef: RefObject<HTMLDivElement | null>;
}

/** The box of an item: a ring at rest, filled with a check when selected. It is a picture of the state; the option carries it for assistive technology. */
const BOX =
  "grid size-[18px] shrink-0 place-items-center rounded-[5px] border border-muted-foreground bg-background text-primary-foreground shadow-xs transition-[background-color,border-color] duration-150 motion-reduce:transition-none group-hover/option:border-foreground group-data-[selected]/option:border-primary group-data-[selected]/option:bg-primary";

/**
 * One of the two lists: a header with a checkbox for all of it and the count,
 * a search field, and a multi-select listbox. The listbox is one tab stop that
 * keeps the focus and points at the item under the cursor with
 * aria-activedescendant, so items can leave it without the focus going
 * anywhere. Arrow keys move the cursor, Shift with them extends a selection,
 * Space toggles, Control A selects all, and Enter moves.
 */
export function Pane({ side, title, items, domId, state, onChange, onMove, fresh, searchable, height, disabled, empty, words, listRef }: PaneProps) {
  const base = useId();
  const [focused, setFocused] = useState(false);
  // Whether the row under the cursor wears a ring: only for a keyboard. A click already shows where it landed with the selection tint, and a list that takes the focus back after a move would otherwise ring a row nobody pointed at.
  const [ring, setRing] = useState(false);
  const visible = useMemo(() => filterItems(items, state.query), [items, state.query]);
  const movable = visible.filter((item) => !item.disabled);
  const here = selectedIn(visible, state.selected);
  const cursor = visible.find((item) => item.id === state.active) ?? (focused ? (here[0] ?? visible[0]) : undefined) ?? null;
  const cursorId = cursor?.id;
  const everySelected = movable.length > 0 && here.length === movable.length;
  const firstFresh = visible.find((item) => fresh.has(item.id))?.id;

  /** Scrolls the list, and only the list, so that an item is in view: the page itself never moves. */
  function reveal(id: string) {
    const box = listRef.current;
    const element = document.getElementById(domId(id));
    if (!box || !element) return;
    const top = element.offsetTop;
    const bottom = top + element.offsetHeight;
    if (top < box.scrollTop) box.scrollTop = top;
    else if (bottom > box.scrollTop + box.clientHeight) box.scrollTop = bottom - box.clientHeight;
  }

  useEffect(() => {
    if (focused && cursorId) reveal(cursorId);
  }, [cursorId, focused]);

  useEffect(() => {
    if (firstFresh) reveal(firstFresh);
  }, [firstFresh]);

  function toggle(id: string) {
    const next = toggled(state.selected, id);
    onChange({ selected: next, anchor: id, seed: next, active: id });
  }

  /** Selects everything from the anchor (or the cursor, when there is none yet) to an item, on top of what was selected before the range began. */
  function range(to: string) {
    const from = state.anchor ?? cursor?.id ?? to;
    const seed = state.anchor ? state.seed : state.selected;
    onChange({ selected: new Set([...seed, ...rangeBetween(visible, from, to)]), anchor: from, seed, active: to });
  }

  function selectAll() {
    const next = new Set([...state.selected, ...movable.map((item) => item.id)]);
    onChange({ selected: next, anchor: null, seed: next });
  }

  function clearShown() {
    const next = new Set([...state.selected].filter((id) => !movable.some((item) => item.id === id)));
    onChange({ selected: next, anchor: null, seed: next });
  }

  /** What Enter or a double click moves: the whole selection when the item is part of it, otherwise just the item. */
  function movingFor(item: TransferItem): string[] {
    if (item.disabled) return [];
    return here.some((other) => other.id === item.id) ? here.map((other) => other.id) : [item.id];
  }

  function onKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    if (disabled || event.altKey) return;
    const { key } = event;
    if (key !== "Tab" && key !== "Shift" && key !== "Control" && key !== "Meta") setRing(true);
    const at = cursor ? visible.findIndex((item) => item.id === cursor.id) : -1;
    const page = Math.max(1, Math.floor((listRef.current?.clientHeight ?? 288) / 48) - 1);
    const go = (index: number) => {
      event.preventDefault();
      const target = visible[Math.min(visible.length - 1, Math.max(0, index))];
      if (!target) return;
      if (event.shiftKey) range(target.id);
      else onChange({ active: target.id });
    };
    if (key === "ArrowDown") return go(at + 1);
    if (key === "ArrowUp") return go(at < 0 ? 0 : at - 1);
    if (key === "PageDown") return go(at + page);
    if (key === "PageUp") return go(at - page);
    if (key === "Home") return go(0);
    if (key === "End") return go(visible.length - 1);
    if (key === " ") {
      event.preventDefault();
      if (!cursor || cursor.disabled) return;
      if (event.shiftKey) range(cursor.id);
      else toggle(cursor.id);
      return;
    }
    if (key === "Enter") {
      event.preventDefault();
      if (cursor) onMove(movingFor(cursor));
      return;
    }
    if ((event.ctrlKey || event.metaKey) && key.toLowerCase() === "a") {
      event.preventDefault();
      selectAll();
    }
  }

  function onPick(item: TransferItem, event: MouseEvent) {
    if (disabled) return;
    if (item.disabled) {
      onChange({ active: item.id });
      return;
    }
    if (event.shiftKey) range(item.id);
    else toggle(item.id);
  }

  const titleId = `${base}-title`;
  const listId = `${base}-list`;
  const style = height === undefined ? undefined : { height };

  return (
    <section data-slot="transfer-list-pane" data-side={side} aria-labelledby={titleId} className="flex min-w-0 flex-col overflow-hidden rounded-xl border border-border bg-card shadow-xs">
      <div className="flex items-center gap-3 border-b border-border px-3 py-2.5">
        <Checkbox
          aria-label={fill(words.selectAll, { list: title })}
          checked={everySelected ? true : here.length > 0 ? "indeterminate" : false}
          disabled={disabled || movable.length === 0}
          onCheckedChange={(next) => (next === true ? selectAll() : clearShown())}
        />
        <p id={titleId} className="min-w-0 truncate text-sm leading-5 font-medium">
          {title}
        </p>
        <p className="ml-auto shrink-0 text-xs leading-4 text-muted-foreground tabular-nums">{fill(words.selectedCount, { selected: here.length, total: items.length })}</p>
      </div>

      {searchable ? (
        <div className="border-b border-border p-2">
          <SearchInput
            value={state.query}
            onValueChange={(query) => onChange({ query, active: null })}
            disabled={disabled}
            placeholder={words.searchPlaceholder}
            aria-label={fill(words.search, { list: title })}
          />
        </div>
      ) : null}

      <div
        ref={listRef}
        id={listId}
        role="listbox"
        aria-multiselectable="true"
        aria-labelledby={titleId}
        aria-disabled={disabled || undefined}
        aria-activedescendant={focused && cursorId ? domId(cursorId) : undefined}
        tabIndex={disabled ? -1 : 0}
        hidden={visible.length === 0}
        onKeyDown={onKeyDown}
        onPointerDown={() => setRing(false)}
        onFocus={(event) => {
          setFocused(true);
          setRing(event.currentTarget.matches(":focus-visible"));
        }}
        onBlur={() => {
          setFocused(false);
          setRing(false);
        }}
        style={style}
        className={cn(
          "relative h-56 overflow-y-auto overscroll-contain outline-none @2xl:h-72",
          "[scrollbar-color:color-mix(in_oklab,var(--foreground)_28%,transparent)_transparent] [scrollbar-width:thin]",
          "focus-visible:ring-[3px] focus-visible:ring-inset focus-visible:ring-ring/40",
        )}
      >
        {visible.map((item) => {
          const selected = state.selected.has(item.id) && !item.disabled;
          return (
            <div
              key={item.id}
              id={domId(item.id)}
              role="option"
              aria-selected={selected}
              aria-disabled={item.disabled || undefined}
              data-selected={selected ? "" : undefined}
              data-active={ring && item.id === cursorId ? "" : undefined}
              data-fresh={fresh.has(item.id) ? "" : undefined}
              onClick={(event) => onPick(item, event)}
              onDoubleClick={() => !disabled && onMove(movingFor(item))}
              className={cn(
                "group/option relative isolate flex min-h-12 w-full cursor-pointer items-center gap-3 border-b border-border/60 px-3 py-2 select-none last:border-b-0",
                "transition-colors duration-150 motion-reduce:transition-none",
                "hover:bg-muted/50 data-[selected]:bg-muted",
                "data-[active]:ring-2 data-[active]:ring-inset data-[active]:ring-ring/60",
                "aria-disabled:cursor-not-allowed aria-disabled:hover:bg-transparent",
              )}
            >
              {/* The tint of an item that has just arrived: it appears at once and fades out slowly, in a layer of its own so that selecting stays quick. */}
              <span
                aria-hidden="true"
                className="pointer-events-none absolute inset-0 -z-10 bg-foreground/10 opacity-0 transition-opacity duration-1000 group-data-[fresh]/option:opacity-100 group-data-[fresh]/option:duration-0 motion-reduce:transition-none"
              />
              <span aria-hidden="true" className={cn(BOX, item.disabled && "opacity-50")}>
                <IconCheck size={12} strokeWidth={2.5} className="opacity-0 transition-opacity duration-150 group-data-[selected]/option:opacity-100 motion-reduce:transition-none" />
              </span>
              <span className={cn("grid min-w-0 flex-1 gap-0.5", item.disabled && "opacity-50")}>
                <span className="truncate text-sm leading-5 font-medium">{item.label}</span>
                {item.description ? <span className="truncate text-xs leading-4 text-muted-foreground">{item.description}</span> : null}
              </span>
              {item.disabled ? <IconLock aria-hidden="true" className="size-3.5 shrink-0 text-muted-foreground" /> : null}
            </div>
          );
        })}
      </div>

      {visible.length === 0 ? (
        <p style={style} className="grid h-56 place-items-center px-6 text-center text-sm text-muted-foreground @2xl:h-72">
          {state.query ? fill(words.noMatches, { query: state.query }) : empty}
        </p>
      ) : null}
    </section>
  );
}

/** One thing that can be moved between the two lists. */
export interface TransferItem {
  /** What `value` holds when the item is chosen. Unique in the list. */
  id: string;
  /** The item's name, and its accessible name. Search reads it. */
  label: string;
  /** A second line under the label: an email address, a role, a type. Search reads it too. */
  description?: string;
  /** The item cannot be selected or moved: a member who cannot be removed, a column that is always shown. */
  disabled?: boolean;
}

/** The headings of the two lists. */
export interface TransferTitles {
  /** The list of things still to choose from. Default "Available". */
  available?: string;
  /** The list of things chosen. Default "Chosen". */
  chosen?: string;
}

/** The two lists. */
export type Side = "available" | "chosen";

/** The words the lists say, for translation. A `{name}` mark in a sentence is filled in. */
export interface TransferListLabels {
  /** The placeholder of both search fields. Default "Search". */
  searchPlaceholder?: string;
  /** Names a search field for a screen reader; `{list}` is the list's title. Default "Search {list}". */
  search?: string;
  /** The count in a list's header; `{selected}` and `{total}`. Default "{selected} of {total} selected". */
  selectedCount?: string;
  /** Names the checkbox in a list's header; `{list}`. Default "Select all in {list}". */
  selectAll?: string;
  /** Names the group of buttons between the lists. Default "Move between lists". */
  moveGroup?: string;
  /** The button that moves the selected items to Chosen. Default "Add selected". */
  add?: string;
  /** The button that moves every item to Chosen. Default "Add all". */
  addAll?: string;
  /** The button that moves the selected items back. Default "Remove selected". */
  remove?: string;
  /** The button that moves every item back. Default "Remove all". */
  removeAll?: string;
  /** What a move button says when a search narrows it to what is shown; `{count}`. Default "{label} ({count} shown)". */
  shown?: string;
  /** What is said after items are added; `{count}`, `{noun}` and `{list}`. Default "{count} {noun} added to {list}". */
  added?: string;
  /** What is said after items are removed; `{count}`, `{noun}` and `{list}`. Default "{count} {noun} removed from {list}". */
  removed?: string;
  /** The word for one item. Default "item". */
  itemOne?: string;
  /** The word for several items. Default "items". */
  itemOther?: string;
  /** What the Available list says when everything has been chosen. Default "Everything has been chosen." */
  emptyAvailable?: string;
  /** What the Chosen list says when nothing has. Default "Nothing chosen yet. Select items in {list} and add them." */
  emptyChosen?: string;
  /** What a list says when the search finds nothing; `{query}`. Default "No matches for “{query}”". */
  noMatches?: string;
}

export const DEFAULT_LABELS = {
  searchPlaceholder: "Search",
  search: "Search {list}",
  selectedCount: "{selected} of {total} selected",
  selectAll: "Select all in {list}",
  moveGroup: "Move between lists",
  add: "Add selected",
  addAll: "Add all",
  remove: "Remove selected",
  removeAll: "Remove all",
  shown: "{label} ({count} shown)",
  added: "{count} {noun} added to {list}",
  removed: "{count} {noun} removed from {list}",
  itemOne: "item",
  itemOther: "items",
  emptyAvailable: "Everything has been chosen.",
  emptyChosen: "Nothing chosen yet. Select items in {list} and add them.",
  noMatches: "No matches for “{query}”",
} satisfies Required<TransferListLabels>;

export type Words = Required<TransferListLabels>;

/** Fills `{name}` marks in a sentence. A mark with no value stays as it is. */
export function fill(template: string, values: Record<string, string | number>): string {
  return template.replace(/\{(\w+)\}/g, (mark, key: string) => (key in values ? String(values[key]) : mark));
}

/** Where one list stands: what is typed in its search field, which items are selected, and where the cursor is. */
export interface PaneState {
  query: string;
  /** The ids selected for moving. Ids that a search hides stay in it, and count again when the search is cleared. */
  selected: ReadonlySet<string>;
  /** The item a range selection grows from. */
  anchor: string | null;
  /** The selection as it was when the anchor was set: a range is added to this, not to whatever the last range left. */
  seed: ReadonlySet<string>;
  /** The item the cursor is on, which the keyboard acts on. */
  active: string | null;
}

export const EMPTY_PANE: PaneState = { query: "", selected: new Set(), anchor: null, seed: new Set(), active: null };

/** Lower case, without accents: "Zoë" is found by "zoe". */
const fold = (text: string): string => text.normalize("NFD").replace(/\p{M}/gu, "").toLowerCase();

/** The items that match a search: every word typed must be in the label or the description. */
export function filterItems(items: readonly TransferItem[], query: string): TransferItem[] {
  const needles = fold(query).split(/\s+/).filter(Boolean);
  if (needles.length === 0) return [...items];
  return items.filter((item) => {
    const text = fold(`${item.label} ${item.description ?? ""}`);
    return needles.every((needle) => text.includes(needle));
  });
}

/** The items of a list that are selected and can be moved, in the order the list shows them. */
export function selectedIn(visible: readonly TransferItem[], selected: ReadonlySet<string>): TransferItem[] {
  return visible.filter((item) => selected.has(item.id) && !item.disabled);
}

/** A copy of a set with one id added, or taken out if it was there. */
export function toggled(set: ReadonlySet<string>, id: string): Set<string> {
  const next = new Set(set);
  if (!next.delete(id)) next.add(id);
  return next;
}

/** The ids that can be selected between two items of a list, both included, whichever comes first. */
export function rangeBetween(visible: readonly TransferItem[], from: string, to: string): string[] {
  const a = visible.findIndex((item) => item.id === from);
  const b = visible.findIndex((item) => item.id === to);
  if (a < 0 || b < 0) return [];
  return visible
    .slice(Math.min(a, b), Math.max(a, b) + 1)
    .filter((item) => !item.disabled)
    .map((item) => item.id);
}

/**
 * Where the cursor goes when items leave a list: the item that now stands
 * where the first of them stood, so the keyboard carries on from the same
 * place. `null` when nothing is left.
 */
export function nextActive(visible: readonly TransferItem[], moved: ReadonlySet<string>): string | null {
  const first = visible.findIndex((item) => moved.has(item.id));
  const rest = visible.filter((item) => !moved.has(item.id));
  return rest[Math.min(Math.max(first, 0), rest.length - 1)]?.id ?? null;
}

/** The chosen ids that are items, once each, in the order they were given. */
export function knownIds(value: readonly string[], items: readonly TransferItem[]): string[] {
  const known = new Set(items.map((item) => item.id));
  return [...new Set(value)].filter((id) => known.has(id));
}
